describe("RegionalTaxCalculator", () => {
  it("throws on invalid defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("throws on invalid region rate", () => {
    expect(() => new RegionalTaxCalculator({ US: -0.01 })).toThrow(RangeError);
    expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
  });

  it("computes tax using region-specific rate", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875, FR: 0.2 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    // 20% of 5000 = 1000
    expect(calc.computeTaxCents(5000, "FR")).toBe(1000);
  });

  it("falls back to defaultRate for unknown regions", () => {
    const calc = new RegionalTaxCalculator({ US: 0.05 }, 0.1);
    // 10% of 2000 = 200
    expect(calc.computeTaxCents(2000, "JP")).toBe(200);
  });

  it("uses 0 as default defaultRate", () => {
    const calc = new RegionalTaxCalculator({ US: 0.05 });
    expect(calc.computeTaxCents(2000, "JP")).toBe(0);
  });

  it("returns 0 for zero or negative taxable", () => {
    const calc = new RegionalTaxCalculator({ US: 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("rounds down to nearest cent", () => {
    const calc = new RegionalTaxCalculator({ US: 0.07 });
    // 7% of 1001 = 70.07 → floor → 70
    expect(calc.computeTaxCents(1001, "US")).toBe(70);
  });
});

