    expect(calc.computeShippingCents([makeLine("a", 2)], 99999)).toBe(500);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("throws when brackets array is empty", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("throws on invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    // no weightGrams set → defaults to 0
    expect(calc.computeShippingCents([makeLine("a", 2)], 5000)).toBe(0);
  });

  it("selects correct bracket for weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g → bracket 500
    expect(calc.computeShippingCents([makeLine("a", 1, 400)], 5000)).toBe(300);
    // 500g → bracket 500 (inclusive)
    expect(calc.computeShippingCents([makeLine("a", 1, 500)], 5000)).toBe(300);
    // 501g → bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 1, 501)], 5000)).toBe(600);
    // 3000g → bracket 5000
    expect(calc.computeShippingCents([makeLine("a", 1, 3000)], 5000)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1500,
    );
    expect(calc.computeShippingCents([makeLine("a", 1, 3000)], 5000)).toBe(1500);
  });

  it("defaults overflow to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 800 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 1, 5000)], 5000)).toBe(800);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 800 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 1, 400)], 5000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 1, 700)], 5000)).toBe(500);
  });
});

