      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const cart = new Cart();
    cart.add(productA, 2); // original subtotal 2000, refreshed to 4000
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.totals.taxCents).toBe(200); // 5% of 4000
  });

  it("inventory check uses reason in InventoryError message", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("discontinued");
  });

  it("generates default message when reason is missing", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      /insufficient stock/,
    );
  });
});

